import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, Color } from 'three/webgpu';
import { texture, mul, float } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
	// Root container
	const root = new Group();

	// Geometry (aspect based on placeholder image 512x320 → 1.6)
	const width = 2; // scene units, arbitrary reasonable size
	const height = width / 1.6;
	const geometry = new PlaneGeometry(width, height, 64, 64);

	// Material with node support
	const material = new MeshStandardNodeMaterial({
		color: new Color('#e8ecf2'), // paper base colour
		metalness: 0.2,
		roughness: 0.6,
	});

	// Load colour texture
	let imageTex = null;
	if (config.imageUrl) {
		ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
			imageTex = tex;
			material.mapNode = texture(tex);
			material.needsUpdate = true;
		});
	}

	// Load depth map for displacement
	let depthTex = null;
	if (config.depthMapUrl) {
		ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
			depthTex = tex;
			// modest displacement strength (0.2 scene units max)
			const dispNode = mul(texture(tex), float(0.2));
			material.displacementNode = dispNode;
			material.needsUpdate = true;
		});
	}

	const mesh = new Mesh(geometry, material);
	mesh.castShadow = true;
	mesh.receiveShadow = true;
	root.add(mesh);

	// -----------------------------------------------------------------
	// Apply cinematic primitives defined in the config
	// -----------------------------------------------------------------
	const primitiveInstances = [];
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const prim of config.cinematicPrimitives) {
			if (typeof ctx.primitives[prim.name] === 'function') {
				const instance = ctx.primitives[prim.name](root, prim.params);
				primitiveInstances.push(instance);
			}
		}
	}
	root.userData._primitiveInstances = primitiveInstances;

	// -----------------------------------------------------------------
	// Interaction handlers
	// -----------------------------------------------------------------
	root.userData.handlers = {};

	// Hover: subtle rise‑in (0.15 scene units)
	root.userData.handlers.hover = () => {
		// Ensure only one hover timeline at a time
		if (root.userData._hoverTimeline) {
			root.userData._hoverTimeline.kill();
		}
		const tl = gsap.timeline();
		tl.to(root.position, {
			y: root.position.y + 0.15,
			duration: 0.7,
			ease: 'power3.out',
		});
		root.userData._hoverTimeline = tl;
	};

	// Click: emit navigation event
	root.userData.handlers.click = () => {
		ctx.emit('hub-home.select', {});
	};

	// -----------------------------------------------------------------
	// Cleanup routine
	// -----------------------------------------------------------------
	root.userData.cleanup = () => {
		// Dispose geometry and material
		geometry.dispose();
		material.dispose();

		// Dispose loaded textures
		if (imageTex) imageTex.dispose();
		if (depthTex) depthTex.dispose();

		// Cleanup primitives
		if (Array.isArray(root.userData._primitiveInstances)) {
			for (const p of root.userData._primitiveInstances) {
				if (p && typeof p.cleanup === 'function') p.cleanup();
			}
		}

		// Kill GSAP timelines
		if (root.userData._hoverTimeline) {
			root.userData._hoverTimeline.kill();
			delete root.userData._hoverTimeline;
		}
	};

	return root;
}
